catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }
    //Type appropriate comment here, and begin script below
    // 监听附件上传变化（attachment_list 是变量名）
    if (newValue) {
        var ga = new GlideAjax('ExcelParserUtil');
        ga.addParam('sysparm_name', 'parseExcel');
        ga.addParam('sysparm_attachment_id', newValue);
        ga.getXMLAnswer(function(response) {
            var data = JSON.parse(response);
            alert(data.status);
            // 清空 MRVS 并回填
            g_form.setValue('asset_list', ''); // 清空
			console.log(JSON.stringify(data.rows));
			g_form.setValue('asset_list', JSON.stringify(data.rows)); // 清空

            // data.rows.forEach(function(row) {
            //     g_form.addNewRow('asset_list'); // 添加新行
            //     var idx = g_form.getEditableRows('asset_list').length - 1;
            //     g_form.setValue('asset_list.' + idx + '.asset_name', row.asset_name);
            //     g_form.setValue('asset_list.' + idx + '.serial_number', row.serial_number);
            //     g_form.setValue('asset_list.' + idx + '.location', row.location);
            // });
        });
    }
}
